sys_ui_page.client_script:
addLoadEvent(function() {

    var summary = GlideModal.get().getPreference('summary') ||
                  GlideModal.get().getPreference('sysparm_summary');

    if (!summary) {
        document.getElementById("resultText").innerText = "No summary available.";
        return;
    }

    // ✅ Step 1: Clean unwanted symbols
    var formatted = summary.replace(/\* /g, '');

    // ✅ Step 2: Section Titles
    formatted = formatted
        .replace(/Incident Summary/g, '<div class="section-title">Incident Summary</div>')
        .replace(/Incident Timeline/g, '<div class="section-title">Incident Timeline</div>')
        .replace(/Lessons Learned/g, '<div class="section-title">Lessons Learned</div>')
        .replace(/Post-Incident Review/g, '<div class="section-title">Post-Incident Review</div>')
        .replace(/Suggestions by AI/g, '<div class="section-title">Suggestions by AI</div>')
        .replace(/Actions Taken/g, '<div class="section-title">Actions Taken</div>')
        .replace(/Resolution/g, '<div class="section-title">Resolution</div>');

    // ✅ Step 3: Key labels
    formatted = formatted
        .replace(/Date:/g, '<div class="row"><span class="label">Date:</span>')
        .replace(/Time:/g, '<div class="row"><span class="label">Time:</span>')
        .replace(/Impact:/g, '<div class="row"><span class="label">Impact:</span>')
        .replace(/Category:/g, '<div class="row"><span class="label">Category:</span>');

    // ✅ Step 4: Convert bullets FIRST (IMPORTANT)
    formatted = formatted
        .replace(/(^|\n)- /g, '$1<div class="bullet">• ');  // start bullet

    // ✅ Step 5: Convert line breaks
    formatted = formatted
        .replace(/\n/g, '</div>');

    // ✅ Step 6: Clean extra divs
    formatted = formatted
        .replace(/<\/div><\/div>/g, '</div>')
        .replace(/<div class="bullet">• <\/div>/g, '');

    document.getElementById("resultText").innerHTML = formatted;

});
